/*
 * PORTED, NEVER RE-DERIVED. Sources, in the product's repo:
 *   orderEntries, aheadGroupOf, KIND_ORDER  -> src/lib/server/timeline/model.ts
 *   previewOf, previewTitle, startsCollapsed -> src/lib/components/course/timeline-preview.ts
 * Proven equal to those functions over this fixture before it was pasted here:
 * same order, same fold, same grouping (TASK-L157 AC3).
 */
const KIND_ORDER = ['evaluation', 'session', 'assignment', 'lesson', 'submission', 'message', 'note', 'signal'];
const STATE_RANK = { done: 0, now: 1, ahead: 2 };
const KIND_RANK = new Map(KIND_ORDER.map((k, i) => [k, i]));


function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}

/* ── THE WORDS LEFT THIS FUNCTION (TASK-L163 §2) ─────────────────────────────
   They were a `COPY` literal here, with a comment saying a string table could
   replace them one day. Two things made that day this one: i18n (they were the
   last 14 strings on /course that did not change language, sprint 46 decision
   003, now reversed) and AUDIENCE — a coach reads this same assembly and must
   not read "Note from your coach" about their own note.

   `Data/Strings` resolves both, in that order, and hands one object down. A
   missing key is not a blank and not a raw key: the base English is always
   underneath, so this reads `COPY.kind[k] || k` for the same reason the kit
   keeps its built-in English. */
const copy = plain(Inputs.copy) || undefined;
const COPY = (copy || {}).timeline || {};

/* ── WHO IS READING (TASK-L163 §3) ───────────────────────────────────────────
   Read from `Data/Strings`, which VALIDATED it, so the audience is decided in
   exactly one place per page rather than typed into two instances that are then
   free to disagree (L102's `isStaffEmail` finding, one layer up). No default
   here either: an unwired input arrives `undefined` and that must be a named
   failure, not the learner's list served to a coach in silence. */
const audience = String(Inputs.audience || '').trim();
if (audience !== 'learner' && audience !== 'coach') {
  throw new Error(
    'Ordered timeline: Audience must be "learner" or "coach", not "' + audience + '" ' +
    '— wire it from Data/Strings, which is where it is decided (TASK-L163 §3).'
  );
}

const all = plain(Inputs.entries) || [];

/* ── ONE ASSEMBLY, TWO PROJECTIONS, AND THEY DIFFER BY EXACTLY THIS ──────────
   PORTED: projectForLearner / projectForCoach -> src/lib/server/timeline/model.ts
   (:1056, :1077, :1094). A learner's payload has never contained a signal — it
   is our INFERENCE about their confusion, and showing somebody a list of the
   times we thought they were stuck is L60's self-certification from the other
   side. A coach's contains everything. That is the WHOLE difference, and the
   entries are loaded once for both on purpose: branching the load is how two
   projections start to disagree about what happened to a person
   (`service.ts:109-111`).

   `message` is NOT filtered here, for either audience — the ROW suppresses it
   for a learner, because that is `PathList`'s layer in the product and each
   decision belongs to the layer that owns it. */
const entries = audience === 'learner' ? all.filter((e) => e.kind !== 'signal') : all;

/* 1 band, 2 dated before undated, 3 at, 4 position, 5 kind, 6 id. Total,
   deterministic and stable — the one property the model owns. */
const ordered = [...entries].sort((a, b) => {
  const band = STATE_RANK[a.state] - STATE_RANK[b.state];
  if (band !== 0) return band;
  const aDated = a.at === null ? 1 : 0;
  const bDated = b.at === null ? 1 : 0;
  if (aDated !== bDated) return aDated - bDated;
  if (a.at !== null && b.at !== null && a.at !== b.at) return a.at < b.at ? -1 : 1;
  if (a.position !== b.position) return a.position - b.position;
  const kind = (KIND_RANK.get(a.kind) || 0) - (KIND_RANK.get(b.kind) || 0);
  if (kind !== 0) return kind;
  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
});

const aheadGroupOf = (e) => (e.state !== 'ahead' ? null : e.kind === 'lesson' ? 'pickup' : 'scheduled');

/* Markdown is carried as TEXT on a folded line, never rendered: a collapsed row
   is one line of chrome and the open card below has the only render path. */
const firstLine = (body, max) => {
  const limit = max || 90;
  const line = String(body || '').split('\n').map((l) => l.trim()).find((l) => l.length > 0) || '';
  const flat = line.replace(/[#*_`>\[\]]/g, '').replace(/\s+/g, ' ').trim();
  return flat.length > limit ? flat.slice(0, limit - 1).trimEnd() + '…' : flat;
};

const previewOf = (e) => {
  switch (e.kind) {
    case 'lesson': return { style: 'text', title: e.title, at: e.at, body: e.rationale };
    /* A cancelled meeting keeps its place on the timeline, so the moment it
       says is startsAt rather than at. */
    case 'session': return { style: 'text', title: e.session.title, at: e.session.startsAt, body: e.session.summary || '' };
    /* The first line of what the coach actually wrote. Eighteen rows reading
       "Note from your coach" is the wall with fewer pixels. */
    case 'note': return { style: 'text', title: firstLine(e.note.body), at: e.at, body: e.note.body };
    /* A review has no title of its own: WHICH of the four points it was is what
       tells one apart from another on a programme that has four. */
    case 'evaluation': return { style: 'evaluation', evaluationKind: e.evaluationKind, at: e.at, body: e.summary || '' };
    case 'assignment': return { style: 'text', title: e.title, at: e.at, body: e.brief };
    /* A submission has no title either. WHICH attempt is what stops a learner
       who revised three times reading three identical rows. */
    case 'submission': return { style: 'submission', attempt: e.attempt, source: e.source, at: e.at, body: '' };
    /* A MESSAGE IS DRAWN FOR A COACH ONLY (L163 decision 2). It belongs to the
       conversation for a learner (L118) and the row is what suppresses it; here
       it gets a preview either way, so that a note anchored to one can still be
       looked up. Its title is the thread's opening line, which is what makes a
       turn identifiable out of context. */
    case 'message': return { style: 'text', title: e.subject, at: e.at, body: e.body || '' };
    /* A SIGNAL HAS NO TITLE OF ITS OWN: WHICH KIND of getting stuck is what
       tells one from another, and it is the one thing a coach reads it for.
       Ported with its words from signal-labels.ts (SIGNAL_LABEL). */
    case 'signal': return { style: 'signal', signalKind: e.signalKind, at: e.at, body: e.utterance || '' };
    default: throw new Error('Ordered timeline: no preview rule for kind "' + String(e.kind) + '"');
  }
};

const previewTitle = (p) => {
  if (p.style === 'text') return p.title;
  if (p.style === 'evaluation') return (COPY.evaluationKind || {})[p.evaluationKind] || p.evaluationKind;
  if (p.style === 'signal') return (COPY.signalLabel || {})[p.signalKind] || p.signalKind;
  return (p.source === 'assignment' ? COPY.foldedAssignment : COPY.foldedArtifact) + p.attempt;
};

/* ── WHERE A SIGNAL HAPPENED ─────────────────────────────────────────────────
   PORTED: signalLocation -> src/lib/components/course/timeline-preview.ts.
   "Said they were confused" is the same sentence on every signal of a kind, so
   without this a coach reads the same row five times. A signal's anchor is a
   bare CONCEPT ID rather than a namespaced entry id — it is written straight
   from `misunderstanding_signals.concept_id` — so it is looked up against the
   lessons on this page, and falls back to the slug when the concept is not one
   of them. The slug is still a location; inventing a title would not be. */
const conceptTitles = new Map(
  (entries || []).filter((e) => e.kind === 'lesson' && e.conceptId).map((e) => [e.conceptId, e.title])
);
const signalLocation = (anchor) => (anchor === null || anchor === undefined ? '' : conceptTitles.get(anchor) || String(anchor));

/* Derived from the programme, never stored: persisting a per-card open/closed
   would let the page revert to the wall it replaced, one expansion at a time.
   A LESSON reads status rather than state, because a LOCKED lesson is ahead too
   and folding it would hide the only thing explaining why it cannot be opened. */
const startsCollapsed = (e) => (e.kind === 'lesson' ? e.status === 'complete' : e.state === 'done');

/* One owner for every date on this page, pinned to UTC. A bare toLocale* or
   toDateString() reads the ambient environment and shows a server's calendar
   day to a learner in another timezone. */
const FORMAT = new Intl.DateTimeFormat('en-GB', { timeZone: 'UTC', day: 'numeric', month: 'short', year: 'numeric' });
const fmtDate = (iso) => (iso ? FORMAT.format(new Date(iso)) : '');

/* ── A SHARED NOTE READS ON THE CARD IT IS ABOUT (sprint 39 §0.3) ────────────
   A note anchored to an entry is drawn UNDER that entry's card, and its own
   standalone row is suppressed ONLY when that entry is on this page. Pointed at
   something that is NOT here it keeps its own card: suppressing unconditionally
   would silently delete something the coach wrote to them, which sprint 39
   drove both ways rather than reasoned about. The fixture carries all three
   cases on purpose — anchored-and-here, anchored-and-elsewhere, and free.

   `onPage` is built from the entries that RENDER rather than from every entry:
   a note anchored to a `message` would otherwise be suppressed into a row that
   never draws, and vanish.

   The COUNT on the folded line is this array's LENGTH, never a number sent
   beside it, so the folded line cannot promise a note the open card does not
   hold. Nothing in this template supplies `comments`: the conversation's write
   path is out of scope this sprint, so the row sends no count rather than a
   hardcoded zero. */
/* ── WHAT THIS AUDIENCE ACTUALLY DRAWS, WHICH IS NOT THE SAME QUESTION ───────
   A note is carried onto the card it is about, and its own card is suppressed
   ONLY when that card is on the page — so "on the page" has to mean *will be
   drawn*, not *was emitted*. A `message` is emitted for both audiences and
   drawn for one, so for a learner it is emitted-and-not-drawn, and a note
   anchored to one would be filed onto a row that never mounts and vanish.

   This MIRRORS the row's own suppression and the two must agree; the row is the
   renderer, this is what decides whether a note has somewhere to land. Written
   as one predicate so there is one sentence to keep true rather than a
   condition repeated at three read sites. */
const drawsFor = (e) => previewOf(e) !== null && !(e.kind === 'message' && audience === 'learner');
const renderable = ordered.filter(drawsFor);
const onPage = new Set(renderable.map((e) => e.id));
const notesByAnchor = new Map();
const carried = new Set();
for (const e of renderable) {
  if (e.kind !== 'note') continue;
  const anchor = e.note && e.note.anchor && e.note.anchor.id;
  if (!anchor || !onPage.has(anchor)) continue;
  if (!notesByAnchor.has(anchor)) notesByAnchor.set(anchor, []);
  notesByAnchor.get(anchor).push(e.note);
  carried.add(e.id);
}

const rows = [];
let lastGroup = null;
for (const entry of renderable) {
  if (carried.has(entry.id)) continue;
  const preview = previewOf(entry);
  const group = aheadGroupOf(entry);
  /* The heading is emitted by the FIRST row of each ahead group, which is how
     one repeater over one ordered list draws two headed groups without the page
     re-deciding the order. */
  const heading = group !== null && group !== lastGroup ? (group === 'scheduled' ? COPY.aheadScheduled : COPY.aheadPickup) : '';
  lastGroup = group;
  rows.push({
    id: entry.id,
    kind: entry.kind,
    state: entry.state,
    /* One object by reference on every row, never 80 string parameters — the
       `Sections for step` pattern. A `For Each` maps a row's properties onto the
       template component's inputs BY NAME, so these two reach the kit node. */
    copy: copy,
    audience: audience,
    kindLabel: (COPY.kind || {})[entry.kind] || entry.kind,
    title: previewTitle(preview),
    body: preview.body || '',
    when: fmtDate(preview.at),
    collapsed: startsCollapsed(entry),
    open: !startsCollapsed(entry),
    heading: heading,
    hasHeading: heading !== '',
    notes: notesByAnchor.get(entry.id) || [],
    /* The signal's location is resolved HERE, where the other entries are, and
       travels on the entry so the kit can draw it without knowing what a concept
       is. Every other kind carries the entry untouched. */
    entry: entry.kind === 'signal' ? Object.assign({}, entry, { locationLabel: signalLocation(entry.anchor) }) : entry
  });
}

Outputs.ordered = rows;
Outputs.loaded();
